// Diagnostic BLE/JK02 par batterie. Lecture seule, aucune publication MQTT.
const d=msg.payload||{};
const now=Date.now();
const all=context.get("bms_health_v1")||{};
const mac=String(d.address||"").toUpperCase();
function get(addr){
 if(!all[addr]) all[addr]={name:"",rssi:null,connected:false,connectedAt:0,
  frames:0,decodes:0,lastFrameAt:0,lastDecodeAt:0,lastType:null,lastSeq:null,
  profileChecks:[],lastError:""};
 return all[addr];
}
const profiles=[
{name:"24S",n:24,mask:54,voltage:118,current:126,soc:141,t1:130,t2:132,mos:134},
{name:"32S",n:32,mask:70,voltage:150,current:158,soc:173,t1:162,t2:164,mos:144}
];
function diagnose(hex){
 const b=Buffer.from(hex,"hex");
 if(b.length!==300||b.subarray(0,4).toString("hex")!=="55aaeb90")
   return ["trame mal formée"];
 const ret=[];
 for(const p of profiles){
  const reasons=[], mask=b.readUInt32LE(p.mask),cells=[];
  for(let i=0;i<p.n;i++) if((mask>>>i)&1)cells.push(b.readUInt16LE(6+2*i)/1000);
  const count=cells.length,pack=b.readUInt32LE(p.voltage)/1000,
        sum=cells.reduce((a,v)=>a+v,0),soc=b[p.soc],
        current=b.readInt32LE(p.current)/1000;
  const temps=[p.t1,p.t2,p.mos].map(x=>b.readInt16LE(x)/10);
  if(count<4)reasons.push("cellules="+count);
  if(cells.some(v=>v<1.5||v>4.5))reasons.push("tension cellule invalide");
  if(pack<5||pack>170)reasons.push("tension pack="+pack.toFixed(1)+"V");
  if(Math.abs(sum-pack)>Math.max(1.5,pack*0.04))
    reasons.push("somme="+sum.toFixed(2)+"V / pack="+pack.toFixed(2)+"V");
  if(soc>100)reasons.push("SOC="+soc);
  if(Math.abs(current)>3000)reasons.push("courant aberrant");
  if(temps.some(t=>t< -80||t>160))reasons.push("température aberrante");
  ret.push(p.name+":"+(reasons.length?reasons.join(", "):
    "plausible "+count+" cellules "+pack.toFixed(2)+"V SOC "+soc+"%"));
 }
 return ret;
}
if(mac){
 const s=get(mac);
 if(d.type==="device_found"){
   s.name=d.name||s.name; if(Number.isFinite(Number(d.rssi)))s.rssi=Number(d.rssi);
 }else if(d.type==="connected"){
   s.connected=true; s.connectedAt=now;s.lastError="";
   s.lastFrameAt=0;s.lastDecodeAt=0;s.profileChecks=[];
 }else if(d.type==="disconnected"){
   s.connected=false;
 }else if(d.type==="connection_error"||d.type==="stream_stale"){
   s.lastError=String(d.error||d.type);
 }else if(d.type===2&&d.crc_ok===true){
   s.frames++;s.lastFrameAt=now;s.lastType=2;s.lastSeq=d.sequence;
   if(typeof d.raw_hex==="string"&&d.raw_hex.length===600)
     s.profileChecks=diagnose(d.raw_hex);
 }else if(d.validation==="provisional_compare_with_BatMON"&&d.source_crc_ok===true){
   s.decodes++;s.lastDecodeAt=now;s.format=d.format||"?";
   s.voltage=d.voltage_v;s.soc=d.soc_pct;
 }
 context.set("bms_health_v1",all);
 return null;
}
if(d!=="health_tick") return null;
const messages=[];
for(const addr of Object.keys(all).sort()){
 const s=all[addr],tail=addr.slice(-5);
 let status=s.connected?"connecté":"déconnecté";
 let frame=s.lastFrameAt?("trame CRC OK il y a "+Math.floor((now-s.lastFrameAt)/1000)+"s"):"aucune trame type 2 reçue";
 let decoding=s.lastDecodeAt?("décodage "+s.format+" il y a "+Math.floor((now-s.lastDecodeAt)/1000)+"s"):
   (s.lastFrameAt?"TRAME REÇUE MAIS NON DÉCODÉE":"pas de mesure décodée");
 let reasons=(!s.lastDecodeAt&&s.lastFrameAt&&s.profileChecks.length)?
   " | "+s.profileChecks.join(" ; "):"";
 let name=s.name&&s.name!=="Unknown"?s.name:"BMS "+tail;
 let line=name+" ["+tail+"] | BLE "+status+
   (s.rssi===null?"":" "+s.rssi+" dBm")+" | "+frame+" | "+decoding+reasons;
 if(s.lastError)line+=" | erreur="+s.lastError;
 messages.push({topic:"jk/"+addr+"/diagnostic",payload:line});
}
if(!messages.length) return null;
node.status({fill:"blue",shape:"dot",text:messages.length+" batterie(s) supervisée(s)"});
return [messages];
